INSERT INTO `posts` (`id`, `title`, `slug`, `description`, `content`, `thumbnail`, `is_featured`, `view_count`, `hashtags`, `author_id`, `created_at`, `updated_at`) VALUES
	(1, 'Cảnh báo chiêu trò lừa đảo qua tin nhắn iMessage và SMS', 'canh-bao-chieu-tro-lua-dao-qua-tin-nhan-imessage-va-sms-gGRdi', 'Gần đây, nhiều người dùng tại Việt Nam liên tục nhận được các tin nhắn lừa đảo qua iMessage và SMS với nội dung tuyển dụng việc làm nhẹ lương cao.', '<h3>Chiêu trò lừa đảo qua tin nhắn bùng phát</h3>\n                <p>Trong thời gian qua, Cục An toàn thông tin (Bộ Thông tin và Truyền thông) đã liên tục nhận được phản ánh của người dân về việc nhận được các tin nhắn rác, tin nhắn lừa đảo qua iMessage trên điện thoại iPhone và các tin nhắn SMS thông thường.</p>\n                <p>Nội dung các tin nhắn này thường đánh vào tâm lý muốn tìm kiếm việc làm thêm của người dân như: "Công ty chúng tôi đang tuyển nhân viên xử lý dữ liệu online, thu nhập từ 500k-1tr/ngày...", hoặc các nội dung về trúng thưởng, vay vốn ngân hàng với lãi suất cực thấp.</p>\n                <h4>Cách thức hoạt động của các đối tượng</h4>\n                <p>Để tăng sự tin tưởng, các đối tượng này thường đính kèm đường link dẫn đến các nhóm Zalo hoặc Telegram. Khi người dùng nhấn vào đường link và tham gia nhóm, chúng sẽ yêu cầu người dùng thực hiện các "nhiệm vụ" như like video YouTube, đánh giá sản phẩm Shopee... và trả một khoản tiền nhỏ ban đầu để mồi chài.</p>\n                <p>Đến khi người dùng nạp số tiền lớn để làm "nhiệm vụ cao cấp", chúng sẽ đưa ra nhiều lý do như sai cú pháp, lỗi hệ thống để yêu cầu người dùng nạp thêm tiền mới cho rút. Cuối cùng, khi nạn nhân không còn khả năng nạp tiền, chúng sẽ xóa nhóm và biến mất.</p>\n                <p><strong>Cơ quan chức năng khuyến cáo:</strong> Người dân tuyệt đối không nhấn vào các đường link lạ từ người gửi không xác định. Không cung cấp thông tin cá nhân hay mã OTP cho bất kỳ ai. Luôn kiểm chứng thông tin tuyển dụng qua các kênh chính thống.</p>', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?w=1000&q=80', 0, 3281, 'canh-bao, lua-dao, tin-nhan-rac, an-ninh-mang', 1, '2026-02-20 00:00:18', '2026-03-17 19:57:58'),
	(2, '6 dấu hiệu nhận biết một trang web lừa đảo bạn cần biết', '6-dau-hieu-nhan-biet-mot-trang-web-lua-dao-ban-can-biet-YtXEF', 'Làm sao để không bị sập bẫy các trang web giả mạo ngân hàng hoặc sàn thương mại điện tử? Hãy xem ngay 6 dấu hiệu nhận biết dưới đây.', '<h3>An toàn khi truy cập Internet: Làm sao để nhận biết website giả mạo?</h3>\n                <p>Với sự phát triển của công nghệ, các website giả mạo ngày càng được thiết kế tinh vi, giống hệt trang thật khiến người dùng rất khó phân biệt. Tuy nhiên, nếu chú ý kỹ, bạn vẫn có thể nhận ra qua 6 dấu hiệu sau:</p>\n                <ol>\n                    <li><strong>Tên miền (Domain) sai lệch:</strong> Đây là dấu hiệu dễ nhận biết nhất. Các trang giả mạo thường dùng tên miền gần giống trang thật như vietcombank-home.vn thay vì vietcombank.com.vn, hoặc sh0pee.vn thay vì shopee.vn.</li>\n                    <li><strong>Không có chứng chỉ SSL (HTTPS):</strong> Các trang web uy tín luôn bắt đầu bằng https:// và có biểu tượng ổ khóa xanh trên thanh địa chỉ. Nếu thấy trang yêu cầu nhập thông tin nhạy cảm mà chỉ có http://, hãy rời đi ngay lập tức.</li>\n                    <li><strong>Yêu cầu cung cấp thông tin quá mức:</strong> Một trang web mua sắm thông thường sẽ không bao giờ yêu cầu bạn nhập mật khẩu email hay mã OTP ngân hàng.</li>\n                    <li><strong>Nội dung sơ sài, sai lỗi chính tả:</strong> Các website lừa đảo thường được làm vội vàng nên hay mắc lỗi chính tả, phông chữ không đồng nhất, hình ảnh mờ nhạt.</li>\n                    <li><strong>Ưu đãi "quá hớp":</strong> Nếu một trang web chào bán iPhone mới nhất với giá chỉ vài triệu đồng, 99% đó là lừa đảo.</li>\n                    <li><strong>Các đường link điều hướng bị lỗi:</strong> Khi bạn click vào các mục như "Giới thiệu", "Liên hệ" trên trang giả mạo, thường sẽ không dẫn đi đâu hoặc quay lại trang chủ.</li>\n                </ol>\n                <p>Hãy luôn luôn cẩn trọng trước khi nhập bất kỳ thông tin quan trọng nào lên mạng. Kiểm tra thật kỹ thanh địa chỉ web là thói mãnh mẽ giúp bạn bảo vệ tài sản của mình.</p>', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1000&q=80', 0, 953, 'security, website, phishing, tips', 1, '2026-03-02 21:41:45', '2026-03-17 19:57:58'),
	(3, 'Hướng dẫn bảo vệ tài khoản ngân hàng trong mùa cao điểm', 'huong-dan-bao-ve-tai-khoan-ngan-hang-trong-mua-cao-diem-ZDvtQ', 'Các vụ mất tiền trong tài khoản ngân hàng liên tục diễn ra do người dân bị lừa cài ứng dụng chứa mã độc. Xem ngay hướng dẫn bảo mật từ chuyên gia.', '<h3>Bảo vệ "ví tiền" online của bạn trước các loại mã độc</h3>\n                <p>Hiện nay, thay vì lừa lấy OTP, tội phạm mạng đã chuyển sang hình thức tinh vi hơn: lừa người dân cài đặt các ứng dụng giả mạo ứng dụng Chính phủ, Thuế, Bảo hiểm xã hội để chiếm quyền điều khiển điện thoại.</p>\n                <p>Khi đã cài đặt, ứng dụng này sẽ bí mật đọc tin nhắn OTP, theo dõi các thao tác cá nhân và tự động thực hiện lệnh chuyển tiền mà người dùng không hề hay biết.</p>\n                <h4>Quy tắc vàng để an toàn</h4>\n                <ul>\n                    <li><strong>Chỉ cài đặt ứng dụng từ cửa hàng chính thống:</strong> Apple App Store và Google Play Store. Tuyệt đối không cài các file .apk từ link lạ.</li>\n                    <li><strong>Không bao giờ chia sẻ OTP:</strong> Dù người gọi có tự xưng là công an, nhân viên ngân hàng hay cán bộ thuế.</li>\n                    <li><strong>Kích hoạt sinh trắc học:</strong> Hãy sử dụng FaceID hoặc vân tay để xác thực giao dịch thay vì chỉ dùng mã PIN.</li>\n                    <li><strong>Hạn chế hạn mức chuyển tiền:</strong> Chỉ để hạn mức đủ dùng trong ngày trên ứng dụng ngân hàng để giảm thiểu rủi ro nếu chẳng may bị hack.</li>\n                </ul>\n                <p>Nếu nghi ngờ điện thoại bị nhiễm mã độc, hãy thực hiện khôi phục cài đặt gốc ngay lập tức để xóa sạch các phần mềm gián điệp và liên hệ ngân hàng để khóa tài khoản tạm thời.</p>', 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=1000&q=80', 0, 5092, 'ngan-hang, bao-mat, app-gia-mao, otp', 1, '2026-03-10 18:51:34', '2026-03-17 19:57:58'),
	(4, 'Lừa đảo mạo danh admin CheckScam để chiếm đoạt tài sản', 'lua-dao-mao-danh-admin-checkscam-de-chiem-doat-tai-san-iLc05', 'Nhiều kẻ xấu đã lập các tài khoản Facebook giả mạo admin của hệ thống CheckScam để lừa phí "kiểm tra thông tin" của người dùng.', '<h3>Cảnh báo mạo danh đội ngũ quản trị CheckScam</h3>\n                <p>Hệ thống CheckScam xin gửi thông báo quan trọng đến toàn thể người dùng về tình trạng mạo danh cán bộ, quản trị viên của chúng tôi để trục lợi cá nhân.</p>\n                <p><strong>Thủ đoạn của chúng:</strong> Các đối tượng sẽ sử dụng tên, hình ảnh và logo của CheckScam để tạo các trang fanpage hoặc tài khoản cá nhân. Khi người dùng nhắn tin nhờ kiểm tra thông tin một tài khoản lừa đảo khác, chúng sẽ yêu cầu đóng phí "tra cứu chuyên sâu" hoặc phí "mở hồ sơ den" với giá từ vài trăm nghìn đến hàng triệu đồng.</p>\n                <p>Chúng tôi xin khẳng định <strong>CheckScam là hệ thống tra cứu MIỄN PHÍ</strong> dành cho cộng đồng. Chúng tôi không bao giờ chủ động nhắn tin yêu cầu người dùng chuyển tiền để kiểm tra thông tin hay giải quyết khiếu nại.</p>\n                <h4>Cách xử lý khi gặp đối tượng mạo danh</h4>\n                <p>Người dân nên thực hiện các bước sau:</p>\n                <ol>\n                    <li>Chụp ảnh màn hình cuộc hội thoại và trang cá nhân của đối tượng.</li>\n                    <li>Gửi phản ánh ngay cho chúng tôi qua kênh liên hệ chính thức trên website.</li>\n                    <li>Báo cáo (Report) tài khoản giả mạo đó cho Facebook/Telegram.</li>\n                </ol>\n                <p>Hãy là người dùng thông thái. Hãy cùng nhau xây dựng một cộng đồng CheckScam minh bạch và an toàn.</p>', 'https://images.unsplash.com/photo-1593113598332-cd288d649433?w=1000&q=80', 0, 6441, 'checkscam, canh-bao, mạo-danh, bao-ve-nguoi-dung', 1, '2026-02-23 10:28:21', '2026-03-17 19:57:58'),
	(5, 'Deepfake - Công nghệ lừa đảo cuộc gọi video tinh vi năm 2024', 'deepfake-cong-nghe-lua-dao-cuoc-goi-video-tinh-vi-nam-2024-xd4tt', 'Tội phạm mạng đang sử dụng AI để giả mạo hình ảnh và giọng nói của người thân để vay tiền. Cách nhận diện và phòng tránh hiệu quả.', '<h3>Khi mắt thấy, tai nghe chưa chắc đã là thật</h3>\n                <p>Deepfake là một công nghệ sử dụng trí tuệ nhân tạo để tạo ra các video giả mạo trông như thật. Gần đây, nhiều người dân đã bị lừa hàng trăm triệu đồng khi nhận được cuộc gọi video từ "con cái" hoặc "người thân" đang ở nước ngoài nhờ chuyển tiền gấp.</p>\n                <p>Các video này thường có hình ảnh mờ ảo, giọng nói hơi đứt quãng và thời gian gọi rất ngắn để nạn nhân không kịp nhận ra sự bất thường.</p>\n                <h4>Dấu hiệu nhận biết cuộc gọi Deepfake</h4>\n                <ul>\n                    <li>Góc nhìn nghiêng của khuôn mặt thường bị biến dạng hoặc mờ đi.</li>\n                    <li>Màu da không đồng nhất giữa khuôn mặt và cổ.</li>\n                    <li>Chuyển động môi không khớp hoàn toàn với lời nói.</li>\n                    <li>Mạch văn và cách dùng từ có vẻ lạ so với thói quen của người thân.</li>\n                </ul>\n                <p><strong>Lời khuyên:</strong> Khi nhận được yêu cầu chuyển tiền qua video call, hãy ngắt máy và gọi lại bằng số điện thoại di động thông thường. Hoặc hãy hỏi một câu hỏi mà chỉ hai người mới biết để kiểm tra danh tính.</p>', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1000&q=80', 0, 8369, 'deepfake, ai, lua-dao, cong-nghe', 1, '2026-02-21 06:23:34', '2026-03-17 19:57:58'),
	(6, 'Lừa đảo tuyển cộng tác viên Shopee, Lazada và TikTok', 'lua-dao-tuyen-cong-tac-vien-shopee-lazada-va-tiktok-Atqyt', 'Chiêu trò "việc nhẹ lương cao" thông qua việc nạp tiền làm nhiệm vụ chốt đơn ảo đang khiến hàng nghìn người sập bẫy mỗi ngày.', '<h3>Sự thật đằng sau những công việc "chốt đơn" kiếm tiền triệu</h3>\n                <p>Các đối tượng lừa đảo thường đăng tin tuyển cộng tác viên trên các mạng xã hội với hứa hẹn thu nhập từ 300k - 500k/ngày chỉ với vài thao tác trên điện thoại.</p>\n                <p>Ban đầu, chúng sẽ cho bạn làm các nhiệm vụ nhỏ với số tiền vài trăm nghìn và chuyển trả hoa hồng sòng phẳng để tạo lòng tin. Khi bạn bắt đầu tin tưởng và nạp số tiền lớn (vài chục triệu), chúng sẽ báo lỗi hệ thống và yêu cầu nạp thêm để "giải cứu" số tiền cũ.</p>\n                <p><strong>Cảnh báo:</strong> Các sàn thương mại điện tử như Shopee, Lazada KHÔNG bao giờ tuyển cộng tác viên làm nhiệm vụ chốt đơn online theo hình thức nạp tiền trước. Tất cả các lời mời gọi nạp tiền để hưởng hoa hồng đều là lừa đảo.</p>', 'https://images.unsplash.com/photo-1556742044-3c52d6e88c62?w=1000&q=80', 0, 4892, 'cong-tac-vien, shopee, lazada, kiem-tien-online', 1, '2026-03-15 03:16:58', '2026-03-17 19:57:58'),
	(7, 'Tổng hợp các sàn giao dịch tiền ảo lừa đảo tại Việt Nam', 'tong-hop-cac-san-giao-dich-tien-ao-lua-dao-tai-viet-nam-hYPoM', 'Danh sách các mô hình đa cấp biến tướng dưới dạng sàn đầu tư Crypto, Forex cam kết lợi nhuận khủng bạn nên tránh xa.', '<h3>Cẩn thận với cam kết "lợi nhuận 1% mỗi ngày"</h3>\n                <p>Đầu tư tài chính luôn đi kèm rủi ro, nhưng các sàn lừa đảo thường cam kết lợi nhuận cố định rất cao mà không cần làm gì. Đây thực chất là mô hình Ponzi - lấy tiền người sau trả cho người trước.</p>\n                <p>Một số đặc điểm của sàn lừa đảo:</p>\n                <ul>\n                    <li>Không có giấy phép hoạt động hợp pháp.</li>\n                    <li>Dùng hoa hồng cao để lôi kéo người khác tham gia (đa cấp).</li>\n                    <li>Khó khăn trong việc rút tiền khi số dư lớn.</li>\n                    <li>Đội ngũ điều hành thường ẩn danh hoặc dùng thông tin giả.</li>\n                </ul>\n                <p>Trước khi đầu tư, hãy tra cứu thông tin sàn trên các cộng đồng uy tín và CheckScam để xem có phản hồi xấu nào không.</p>', 'https://images.unsplash.com/photo-1621761191319-c6fb62004040?w=1000&q=80', 0, 7573, 'crypto, forex, dau-tu, ponzi', 1, '2026-02-26 09:32:29', '2026-03-17 19:57:58'),
	(8, 'Cảnh báo lừa đảo chiếm đoạt sim điện thoại để hack ngân hàng', 'canh-bao-lua-dao-chiem-doat-sim-dien-thoai-de-hack-ngan-hang-XEI2K', 'Kẻ gian mạo danh nhân viên nhà mạng yêu cầu hỗ trợ nâng cấp sim 4G/5G từ xa để chiếm quyền kiểm soát số điện thoại của nạn nhân.', '<h3>Chiêu trò nâng cấp SIM từ xa nguy hiểm như thế nào?</h3>\n                <p>Đối tượng sẽ gọi điện tự xưng là nhân viên Viettel, MobiFone hoặc VinaPhone và hướng dẫn bạn soạn tin nhắn theo cú pháp để nâng cấp sim 4G miễn phí. Thực chất, đây là cú pháp để kích hoạt sim trắng của chúng và hủy sim đang dùng của bạn.</p>\n                <p>Sau khi chiếm được số điện thoại, chúng sẽ dùng chức năng "quên mật khẩu" của các ứng dụng ngân hàng, ví điện tử để lấy mã OTP và rút sạch tiền trong tài khoản.</p>\n                <p><strong>Cách phòng tránh:</strong> Chỉ thực hiện nâng cấp sim tại các cửa hàng giao dịch trực tiếp của nhà mạng. Tuyệt đối không soạn tin nhắn theo hướng dẫn của người lạ qua điện thoại.</p>', 'https://images.unsplash.com/photo-1562408590-e32931084e23?w=1000&q=80', 0, 2568, 'sim-card, hacker, ngan-hang, bao-mat', 1, '2026-02-21 00:17:36', '2026-03-17 19:57:58'),
	(9, 'Cách lấy lại tài khoản Facebook bị hack nhanh chóng và an toàn', 'cach-lay-lai-tai-khoan-facebook-bi-hack-nhanh-chong-va-an-toan-p7IfI', 'Tài khoản của bạn bị đổi email và số điện thoại? Đừng quá lo lắng, hãy làm theo các bước dưới đây để yêu cầu Facebook hỗ trợ.', '<h3>Quy trình phục hồi tài khoản Facebook bị xâm nhập</h3>\n                <p>Khi bị hacker chiếm quyền điều khiển, điều đầu tiên cần làm là không được hoảng loạn. Facebook cung cấp các công cụ để người dùng chính chủ lấy lại quyền truy cập.</p>\n                <ol>\n                    <li>Truy cập địa chỉ: facebook.com/hacked</li>\n                    <li>Sử dụng thiết bị và mạng Internet (Wi-Fi) mà bạn thường xuyên dùng để đăng nhập trước đây.</li>\n                    <li>Cung cấp giấy tờ tùy thân (CCCD/Bằng lái) nếu được yêu cầu.</li>\n                    <li>Xác minh danh tính qua email cũ hoặc số điện thoại cũ đã từng liên kết.</li>\n                </ol>\n                <p>Sau khi lấy lại được, hãy kích hoạt ngay bảo mật 2 lớp (2FA) bằng ứng dụng Google Authenticator để ngăn chặn việc bị hack trong tương lai.</p>', 'https://images.unsplash.com/photo-1611162617213-7d7a39e9b1d7?w=1000&q=80', 0, 3536, 'facebook, hacked, security, 2fa', 1, '2026-02-20 13:37:01', '2026-03-17 19:57:58'),
	(10, 'Top 5 ví điện tử an toàn và phổ biến nhất tại Việt Nam 2024', 'top-5-vi-dien-tu-an-toan-va-pho-bien-nhat-tai-viet-nam-2024-VQtSv', 'So sánh ưu nhược điểm và tính năng bảo mật của MoMo, ZaloPay, Viettel Money, VNPay và ShopeePay.', '<h3>Lựa chọn ví điện tử thông minh cho giao dịch hàng ngày</h3>\n                <p>Ví điện tử đã trở thành một phần không thể thiếu trong đời sống số. Tuy nhiên, tính an toàn luôn được đặt lên hàng đầu. Các ví lớn tại Việt Nam đều đạt chứng chỉ bảo mật quốc tế PCI DSS.</p>\n                <p><strong>MoMo:</strong> Hệ sinh thái lớn nhất, bảo mật nhiều lớp nhưng đôi khi ứng dụng hơi nặng.</p>\n                <p><strong>ZaloPay:</strong> Tích hợp ngay trong Zalo, giao dịch cực kỳ nhanh chóng.</p>\n                <p><strong>Viettel Money:</strong> An toàn cao, hỗ trợ tốt cả những nơi không có mạng Internet qua USSD.</p>\n                <p>Dù dùng ví nào, bạn cũng nên đặt mật khẩu khác nhau và không bao giờ liên kết quá nhiều tiền từ tài khoản ngân hàng chính vào ví.</p>', 'https://images.unsplash.com/photo-1512075135822-67cdd9dd7314?q=80&w=1000&auto=format&fit=crop', 0, 9012, 'vi-dien-tu, momo, zalopay, vnpay', 1, '2026-02-19 02:22:10', '2026-03-17 19:57:58'),
	(11, 'Cảnh báo dịch vụ "Thu phí lấy lại tiền lừa đảo" trên mạng', 'canh-bao-dich-vu-thu-phi-lay-lai-tien-lua-dao-tren-mang-SmrXL', 'Lừa đảo chồng lừa đảo! Cảnh giác với các nhóm cam kết "hack vào hệ thống đối phương" để đòi lại tiền đã mất cho nạn nhân.', '<h3>Đừng để bị lừa thêm một lần nữa</h3>\n                <p>Sau khi bị lừa mất tiền, nhiều người có tâm lý nôn nóng muốn lấy lại nên tìm đến các dịch vụ "hỗ trợ thu hồi vốn". Các đối tượng này tự xưng là công ty luật, hacker mũ trắng hoặc cán bộ an ninh mạng.</p>\n                <p>Chúng sẽ yêu cầu bạn đóng phí "mở hồ sơ", "lệnh rút tiền" hoặc "phí phần mềm quét dữ liệu". Sau khi nhận tiền, chúng sẽ lập tức chặn liên lạc. Thực tế, không có cá nhân hay tổ chức nào có thể hack vào tài khoản của kẻ lừa đảo để lấy lại tiền cho bạn ngoài cơ quan công an.</p>', 'https://images.unsplash.com/photo-1614064641938-3bbee52942c7?w=1000&q=80', 1, 5795, 'canh-bao, lua-dao, thu-hoi-von, hack', 1, '2026-02-24 07:43:19', '2026-03-17 19:57:58'),
	(12, 'Phân biệt Telegram thật và các nhóm Telegram lừa đảo Crypto', 'phan-biet-telegram-that-va-cac-nhom-telegram-lua-dao-crypto-06R9s', 'Làm thế nào để nhận biết một dự án Crypto uy tín trên Telegram giữa hàng nghìn nhóm mời gọi đầu tư mỗi ngày.', '<h3>Telegram - Mảnh đất màu mỡ của tội phạm mạng</h3>\n                <p>Telegram nổi tiếng với tính ẩn danh cao, nên đây cũng là nơi tội phạm lừa đảo hoạt động mạnh nhất. Chúng thường thêm bạn vào các nhóm "kèo thơm", "tín hiệu bay" mà chưa bao giờ bạn đăng ký tham gia.</p>\n                <p>Dấu hiệu nhóm lừa đảo:</p>\n                <ul>\n                    <li>Số lượng thành viên ảo (bot) rất lớn nhưng tương tác kém.</li>\n                    <li>Chặn chức năng chat của thành viên, chỉ Admin được đăng bài.</li>\n                    <li>Yêu cầu chuyển tiền trực tiếp cho Admin để mua token "giá rẻ".</li>\n                </ul>\n                <p>Hãy luôn kiểm tra tính minh bạch của dự án và tuyệt đối không click vào các file .file đính kèm trong các nhóm lạ.</p>', 'https://images.unsplash.com/photo-1620321023374-d1a68fbc720d?w=1000&q=80', 1, 920, 'telegram, crypto, blockchain, airdrop', 1, '2026-03-07 02:45:30', '2026-03-17 19:57:58'),
	(13, 'Lừa đảo mạo danh cơ quan Thuế yêu cầu cài app quyết toán thuế', 'lua-dao-mao-danh-co-quan-thue-yeu-cau-cai-app-quyet-toan-thue-ugwwQ', 'Thủ đoạn lừa đảo này đang bùng phát trong mùa quyết toán thuế, khiến nhiều doanh nghiệp và cá nhân bị mất quyền kiểm soát điện thoại.', '<h3>Cảnh báo về ứng dụng "Tổng cục Thuế" giả mạo</h3>\n                <p>Kẻ lừa đảo gọi điện hướng dẫn cài đặt ứng dụng có tên "eTax Mobile" hoặc "Tổng cục Thuế" nhưng qua một đường link gửi qua Zalo/iMessage (file .apk). Ứng dụng này chứa mã độc cho phép hacker theo dõi mọi hoạt động của bạn.</p>\n                <p><strong>Lưu ý:</strong> Cơ quan Thuế chỉ có ứng dụng chính thức trên Store của Apple và Google. Cán bộ thuế không bao giờ yêu cầu người dân cài app qua link lạ hay cung cấp thông tin bí mật qua điện thoại.</p>', 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=1000&q=80', 0, 648, 'thue, etax, lua-dao, bao-mat', 1, '2026-03-15 03:01:43', '2026-03-17 19:57:58'),
	(14, 'Tầm quan trọng của việc kiểm tra STK trước khi chuyển tiền', 'tam-quan-trong-cua-viec-kiem-tra-stk-truoc-khi-chuyen-tien-D2L0l', 'Tại sao bạn nên tra cứu số tài khoản trên CheckScam trước khi thực hiện các giao dịch mua bán online với người lạ?', '<h3>Phòng bệnh hơn chữa bệnh: Quy tắc 3 phút an toàn</h3>\n                <p>Mỗi ngày có hàng trăm số tài khoản lừa đảo được cập nhật lên hệ thống CheckScam. Chỉ cần dành ra 3 phút truy cập website để tra cứu:</p>\n                <ul>\n                    <li>Số tài khoản ngân hàng.</li>\n                    <li>Số điện thoại liên hệ.</li>\n                    <li>Link Facebook/Telegram của người bán.</li>\n                </ul>\n                <p>Nếu kết quả hiện "Bị báo cáo lừa đảo", hãy dừng ngay giao dịch. Đây là cách đơn giản nhất để bảo vệ túi tiền của chính bạn khỏi những kẻ gian gian lận trên mạng.</p>', 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?q=80&w=1000&auto=format&fit=crop', 0, 5037, 'checkscam, giao-dich, an-toan, ngan-hang', 1, '2026-03-12 11:34:32', '2026-03-17 19:57:58'),
	(15, 'Chiêu trò lừa đảo qua ứng dụng hẹn hò Tinder và Bumble', 'chieu-tro-lua-dao-qua-ung-dung-hen-ho-tinder-va-bumble-CFLVU', 'Cảnh báo về các "nữ thần" mời gọi đầu tư sàn chứng khoán hoặc Crypto sau khi làm quen qua các ứng dụng hẹn hò.', '<h3>Mắc bẫy "tình" kiêm bẫy "tiền" trên app hẹn hò</h3>\n                <p>Nhiều nam giới đã trở thành nạn nhân của chiêu trò này. Sau vài ngày nhắn tin ngọt ngào, đối phương sẽ bắt đầu khoe về lợi nhuận từ việc đầu tư và ngỏ ý "dẫn dắt" bạn cùng tham gia.</p>\n                <p>Thực chất, các sàn giao dịch này đều do chúng kiểm soát. Ban đầu bạn sẽ thắng, nhưng khi nạp tiền lớn, tài khoản của bạn sẽ bị khóa hoặc không thể rút được. Hãy tỉnh táo, tình yêu không bao giờ đến dễ dàng kèm theo các lời mời đầu tư tài chính.</p>', 'https://images.unsplash.com/photo-1516245834210-c4c142787335?w=1000&q=80', 0, 7582, 'hen-ho, tinder, lua-dao-tc, scammer', 1, '2026-03-04 19:32:52', '2026-03-17 19:57:58'),
	(16, 'Hướng dẫn báo cáo tài khoản lừa đảo lên hệ thống CheckScam', 'huong-dan-bao-cao-tai-khoan-lua-dao-len-he-thong-checkscam-Ew8Q7', 'Bạn vừa bị lừa hoặc phát hiện kẻ gian? Hãy xem hướng dẫn cách gửi bằng chứng báo cáo để cảnh báo cho cộng đồng.', '<h3>Cùng nhau xây dựng cộng đồng mạng sạch bóng lừa đảo</h3>\n                <p>Để báo cáo một vụ lừa đảo thành công, bạn cần chuẩn bị đầy đủ các bằng chứng sau:</p>\n                <ol>\n                    <li>Ảnh chụp màn hình các tin nhắn giao dịch.</li>\n                    <li>Ảnh chụp bằng chứng chuyển khoản thành công (Bill ngân hàng).</li>\n                    <li>Thông tin chi tiết về đối tượng (STK, SĐT, Link trang cá nhân).</li>\n                </ol>\n                <p>Báo cáo của bạn sẽ giúp hàng nghìn người khác không bị mất tiền như bạn. Hãy chung tay bảo vệ cộng đồng!</p>', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=1000&auto=format&fit=crop', 0, 6450, 'report, checkscam, cong-dong, canh-bao', 1, '2026-02-21 21:09:29', '2026-03-17 19:57:58'),
	(17, 'Lừa đảo "nhận quà miễn phí" nhưng phải trả phí vận chuyển cao', 'lua-dao-nhan-qua-mien-phi-nhung-phai-tra-phi-van-chuyen-cao-g5YrN', 'Chiêu trò tặng nước hoa, mỹ phẩm hay đồ điện tử 0 đồng nhưng khách hàng phải trả phí ship "trên trời".', '<h3>Cái bẫy quà tặng 0 đồng bạn nên tránh</h3>\n                <p>Kẻ gian gọi điện thông báo bạn là khách hàng may mắn được tặng một món quà giá trị như nước hoa Chanel hay đồng hồ thông minh. Bạn chỉ cần thanh toán phí vận chuyển và phí thuế hải quan từ 200k - 500k.</p>\n                <p>Tuy nhiên, khi nhận hàng, bên trong chỉ là rác hoặc các vật dụng rẻ tiền trị giá vài nghìn đồng. Đây là hình thức lừa đảo tinh vi dựa trên tâm lý thích đồ miễn phí của người dùng.</p>', 'https://images.unsplash.com/photo-1513885535751-8b9238bd345a?w=1000&q=80', 0, 9919, 'qua-tang, lua-dao, freebie, ship-cod', 1, '2026-03-13 14:19:01', '2026-03-17 19:57:58'),
	(18, 'Rủi ro khi mua tài khoản Game, Netflix giá rẻ trên mạng', 'rui-ro-khi-mua-tai-khoan-game-netflix-gia-re-tren-mang-booyj', 'Tại sao các tài khoản Netflix, Spotify hay Game Steam giá rẻ thường bị quét và khóa sau vài ngày sử dụng?', '<h3>Tiền mất tật mang khi mua hàng "lậu"</h3>\n                <p>Các tài khoản giá rẻ được bán tràn lan trên mạng thường có nguồn gốc từ việc sử dụng thẻ tín dụng chùa (CC) hoặc tận dụng các lỗ hồng của dịch vụ. Các nền tảng như Netflix hay Spotify liên tục quét các tài khoản này.</p>\n                <p>Khi bị phát hiện, tài khoản của bạn sẽ bị khóa vĩnh viễn và người bán cũng sẽ "bay màu" khiến bạn không thể bảo hành. Hãy đăng ký trực tiếp từ nhà phát hành để được hưởng dịch vụ tốt nhất và an toàn nhất.</p>', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?w=1000&q=80', 0, 8394, 'netflix, game, premium, lua-dao', 1, '2026-02-17 23:14:59', '2026-03-17 19:57:58'),
	(19, 'Quy trình đóng bảo hiểm tại CheckScam đảm bảo uy tín', 'quy-trinh-dong-bao-hiem-tai-checkscam-dam-bao-uy-tin-VdJB8', 'Tìm hiểu về hệ thống quỹ bảo hiểm tại CheckScam và cách nó bảo vệ quyền lợi cho cả người mua và người bán.', '<h3>Xây dựng lòng tin bằng quỹ bảo hiểm CheckScam</h3>\n                <p>Hệ thống Đóng Bảo Hiểm tại CheckScam giúp định danh những người làm dịch vụ uy tín. Khi một cá nhân đóng bảo hiểm, số tiền đó sẽ được hệ thống giữ lại để bồi thường nếu có sự cố gian lận xảy ra.</p>\n                <p>Ưu điểm cho người đóng bảo hiểm:</p>\n                <ul>\n                    <li>Tăng độ uy tín trong mắt khách hàng.</li>\n                    <li>Được ưu tiên hiển thị trên hệ thống.</li>\n                    <li>Hỗ trợ giải quyết tranh chấp nhanh chóng.</li>\n                </ul>\n                <p>Hãy liên hệ ngay với Admin chính thức để tìm hiểu về mức phí và quy trình tham gia bảo hiểm chuyên nghiệp.</p>', 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?q=80&w=1000&auto=format&fit=crop', 0, 1310, 'bao-hiem, uy-tin, checkscam, quy-bao-hiem', 1, '2026-02-27 22:20:15', '2026-03-17 19:57:58'),
	(20, 'Cảnh báo lừa đảo trúng thưởng qua điện thoại và Facebook', 'canh-bao-lua-dao-trung-thuong-qua-dien-thoai-va-facebook-BrpHh', 'Bạn nhận được thông báo trúng thưởng xe SH hoặc 100 triệu đồng từ Messenger? Đọc ngay bài viết để không mất tiền oan.', '<h3>Trúng thưởng giả - Mất tiền thật</h3>\n                <p>Đây là chiêu trò cổ điển nhưng vẫn rất nhiều người sập bẫy. Kẻ gian mạo danh nhân viên của Facebook, Viettel hoặc tập đoàn lớn báo bạn đã trúng thưởng phần quà cực lớn.</p>\n                <p>Chúng yêu cầu bạn chuyển trước phí làm thủ tục hồ sơ hoặc phí vận chuyển quà tặng. Đừng bao giờ tin vào những giải thưởng "từ trên trời rơi xuống" mà bạn chưa bao giờ tham gia dự thi.</p>', 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=1000&q=80', 0, 8110, 'trung-thuong, lua-dao, Messenger, canh-bao', 1, '2026-03-17 19:18:41', '2026-03-17 19:57:58'),
	(21, 'Lừa đảo đầu tư chứng khoán quốc tế và các sàn BO', 'lua-dao-dau-tu-chung-khoan-quoc-te-va-cac-san-bo-2kAD7', 'Phân tích mô hình hoạt động của các sàn nhị phân (BO) và rủi ro cháy tài khoản khi nghe theo các "chuyên gia đọc lệnh".', '<h3>Sự thật về các sàn giao dịch quyền chọn nhị phân</h3>\n                <p>Các sàn BO thực chất là một hình thức đánh bạc đội lốt đầu tư tài chính. Người chơi chỉ có 2 lựa chọn lên hoặc xuống trong thời gian cực ngắn. Các "chuyên gia" thường khoe cuộc sống sang chảnh để lôi kéo người chơi nạp tiền.</p>\n                <p>Hệ thống sàn thường có thể can thiệp vào kết quả giao dịch ở những giây cuối cùng. Hãy tránh xa các sàn giao dịch này nếu không muốn trắng tay trong một đêm.</p>', 'https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?q=80&w=1000&auto=format&fit=crop', 0, 1894, 'bo, chung-khoan, dau-tu, rui-ro', 1, '2026-02-20 04:58:04', '2026-03-17 19:57:58'),
	(22, 'Bảo mật thông tin cá nhân trên mạng xã hội như thế nào?', 'bao-mat-thong-tin-ca-nhan-tren-mang-xa-hoi-nhu-the-nao-Xpibq', 'Những thói quen vô tình của bạn đang tạo điều kiện cho hacker chiếm đoạt tài khoản và thông tin cá nhân.', '<h3>Dữ liệu cá nhân: Tài sản quý giá nhất trong kỷ nguyên số</h3>\n                <p>Hacker thường thu thập thông tin của bạn từ những chi tiết nhỏ nhất:</p>\n                <ul>\n                    <li>Ngày tháng năm sinh hiển thị công khai.</li>\n                    <li>Sử dụng số điện thoại cá nhân làm mật khẩu.</li>\n                    <li>Click vào các liên kết khảo sát, đố vui trên tường của bạn bè.</li>\n                </ul>\n                <p>Hãy ẩn bớt thông tin nhạy cảm, chỉ để chế độ bạn bè và thường xuyên kiểm tra danh sách các ứng dụng đang có quyền truy cập vào Facebook của bạn.</p>', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1000&q=80', 0, 2775, 'privacy, security, social-media, tips', 1, '2026-03-16 17:53:52', '2026-03-17 19:57:58'),
	(23, 'Cảnh báo lừa đảo vay tiền qua ứng dụng tín dụng đen', 'canh-bao-lua-dao-vay-tien-qua-ung-dung-tin-dung-den-AtlOc', 'Những hệ lụy kinh khủng khi cài đặt các app vay tiền dễ dàng chỉ cần CCCD và quyền truy cập danh bạ điện thoại.', '<h3>Ám ảnh app vay tiền và chiêu trò "đòi nợ kiểu xã hội đen"</h3>\n                <p>Các app vay tiền lừa đảo thường quảng cáo vay tiền không lãi suất, nhưng thực chất lãi suất cực cao dưới các loại phí dịch vụ. Khi nợ quá hạn, chúng sẽ dùng hình ảnh và thông tin của bạn để bêu rếu lên mạng xã hội và gọi điện khủng bố người thân trong danh bạ.</p>\n                <p>Duyên nợ với các app này rất khó dứt. Hãy tìm đến các tổ chức tài chính chính thống và uy tín nếu thực sự cần vay vốn.</p>', 'https://images.unsplash.com/photo-1559526324-4b87b5e36e44?w=1000&q=80', 0, 1079, 'vay-tien, app-vay, tin-dung-den, canh-bao', 1, '2026-03-01 08:44:19', '2026-03-17 19:57:58'),
	(24, 'Hướng dẫn kiểm tra iPhone cũ khi mua qua mạng xã hội', 'huong-dan-kiem-tra-iphone-cu-khi-mua-qua-mang-xa-hoi-XtyYr', 'Tránh mua phải iPhone dựng, iPhone lock hoặc iPhone bị dính iCloud ẩn qua các nhóm mua bán điện thoại cũ.', '<h3>Kinh nghiệm mua đồ công nghệ cũ online an toàn</h3>\n                <p>Mua iPhone cũ qua Facebook Marketplace hay hội nhóm tiềm ẩn rất nhiều rủi ro. Hãy yêu cầu người bán giao dịch trực tiếp hoặc qua trung gian uy tín.</p>\n                <p>Các bước kiểm tra cơ bản:</p>\n                <ul>\n                    <li>Kiểm tra IMEI/Serial trên trang chủ Apple.</li>\n                    <li>Kiểm tra chức năng FaceID hoặc TouchID xem có hoạt động ổn định không.</li>\n                    <li>Khôi phục cài đặt gốc ngay tại chỗ để tránh iCloud ẩn.</li>\n                </ul>\n                <p>Đừng vì quá ham rẻ mà mua phải những chiếc máy "mất vân, hư cam" hoặc máy đã qua sửa chữa nặng nề.</p>', 'https://images.unsplash.com/photo-1616348436168-de43ad0db179?q=80&w=1000&auto=format&fit=crop', 0, 6084, 'iphone, cong-nghe, mua-ban, tips', 1, '2026-03-06 15:18:32', '2026-03-17 19:57:58'),
	(25, 'Lừa đảo mạo danh Công an thông báo vi phạm giao thông "phạt nguội"', 'lua-dao-mao-danh-cong-an-thong-bao-vi-pham-giao-thong-phat-nguoi-FxgU9', 'Cuộc gọi tự xưng Công an giao thông thông báo bạn có biên bản phạt nguội và yêu cầu nộp tiền qua tài khoản cá nhân.', '<h3>Cảnh giác với các cuộc gọi thông báo "phạt nguội"</h3>\n                <p>Tội phạm mạo danh cán bộ CSGT gọi điện đe dọa nạn nhân liên quan đến các vụ án giao thông nghiêm trọng hoặc có biên bản phạt nguội chưa nộp. Chúng yêu cầu bạn chuyển khoản ngay để "đình chỉ vụ việc".</p>\n                <p><strong>Lưu ý quan trọng:</strong> Cơ quan Công an chỉ làm việc thông qua giấy mời, giấy triệu tập tại trụ sở chính thức. Mọi yêu cầu chuyển tiền qua điện thoại đều là hành vi lừa đảo chiếm đoạt tài sản.</p>', 'https://images.unsplash.com/photo-1589829085413-56de8ae18c73?q=80&w=1000&auto=format&fit=crop', 0, 1603, 'cong-an, phat-nguoi, lua-dao, canh-bao', 1, '2026-03-14 12:38:18', '2026-03-17 19:57:58'),
	(26, 'Cảnh báo chiêu trò lừa đảo qua tin nhắn iMessage và SMS', 'canh-bao-chieu-tro-lua-dao-qua-tin-nhan-imessage-va-sms-seYVT', 'Gần đây, nhiều người dùng tại Việt Nam liên tục nhận được các tin nhắn lừa đảo qua iMessage và SMS với nội dung tuyển dụng việc làm nhẹ lương cao.', '<h3>Chiêu trò lừa đảo qua tin nhắn bùng phát</h3>\n                <p>Trong thời gian qua, Cục An toàn thông tin (Bộ Thông tin và Truyền thông) đã liên tục nhận được phản ánh của người dân về việc nhận được các tin nhắn rác, tin nhắn lừa đảo qua iMessage trên điện thoại iPhone và các tin nhắn SMS thông thường.</p>\n                <p>Nội dung các tin nhắn này thường đánh vào tâm lý muốn tìm kiếm việc làm thêm của người dân như: "Công ty chúng tôi đang tuyển nhân viên xử lý dữ liệu online, thu nhập từ 500k-1tr/ngày...", hoặc các nội dung về trúng thưởng, vay vốn ngân hàng với lãi suất cực thấp.</p>\n                <h4>Cách thức hoạt động của các đối tượng</h4>\n                <p>Để tăng sự tin tưởng, các đối tượng này thường đính kèm đường link dẫn đến các nhóm Zalo hoặc Telegram. Khi người dùng nhấn vào đường link và tham gia nhóm, chúng sẽ yêu cầu người dùng thực hiện các "nhiệm vụ" như like video YouTube, đánh giá sản phẩm Shopee... và trả một khoản tiền nhỏ ban đầu để mồi chài.</p>\n                <p>Đến khi người dùng nạp số tiền lớn để làm "nhiệm vụ cao cấp", chúng sẽ đưa ra nhiều lý do như sai cú pháp, lỗi hệ thống để yêu cầu người dùng nạp thêm tiền mới cho rút. Cuối cùng, khi nạn nhân không còn khả năng nạp tiền, chúng sẽ xóa nhóm và biến mất.</p>\n                <p><strong>Cơ quan chức năng khuyến cáo:</strong> Người dân tuyệt đối không nhấn vào các đường link lạ từ người gửi không xác định. Không cung cấp thông tin cá nhân hay mã OTP cho bất kỳ ai. Luôn kiểm chứng thông tin tuyển dụng qua các kênh chính thống.</p>', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?w=1000&q=80', 0, 7057, 'canh-bao, lua-dao, tin-nhan-rac, an-ninh-mang', 1, '2026-03-16 22:15:53', '2026-03-17 19:57:58'),
	(27, '6 dấu hiệu nhận biết một trang web lừa đảo bạn cần biết', '6-dau-hieu-nhan-biet-mot-trang-web-lua-dao-ban-can-biet-RTYL9', 'Làm sao để không bị sập bẫy các trang web giả mạo ngân hàng hoặc sàn thương mại điện tử? Hãy xem ngay 6 dấu hiệu nhận biết dưới đây.', '<h3>An toàn khi truy cập Internet: Làm sao để nhận biết website giả mạo?</h3>\n                <p>Với sự phát triển của công nghệ, các website giả mạo ngày càng được thiết kế tinh vi, giống hệt trang thật khiến người dùng rất khó phân biệt. Tuy nhiên, nếu chú ý kỹ, bạn vẫn có thể nhận ra qua 6 dấu hiệu sau:</p>\n                <ol>\n                    <li><strong>Tên miền (Domain) sai lệch:</strong> Đây là dấu hiệu dễ nhận biết nhất. Các trang giả mạo thường dùng tên miền gần giống trang thật như vietcombank-home.vn thay vì vietcombank.com.vn, hoặc sh0pee.vn thay vì shopee.vn.</li>\n                    <li><strong>Không có chứng chỉ SSL (HTTPS):</strong> Các trang web uy tín luôn bắt đầu bằng https:// và có biểu tượng ổ khóa xanh trên thanh địa chỉ. Nếu thấy trang yêu cầu nhập thông tin nhạy cảm mà chỉ có http://, hãy rời đi ngay lập tức.</li>\n                    <li><strong>Yêu cầu cung cấp thông tin quá mức:</strong> Một trang web mua sắm thông thường sẽ không bao giờ yêu cầu bạn nhập mật khẩu email hay mã OTP ngân hàng.</li>\n                    <li><strong>Nội dung sơ sài, sai lỗi chính tả:</strong> Các website lừa đảo thường được làm vội vàng nên hay mắc lỗi chính tả, phông chữ không đồng nhất, hình ảnh mờ nhạt.</li>\n                    <li><strong>Ưu đãi "quá hớp":</strong> Nếu một trang web chào bán iPhone mới nhất với giá chỉ vài triệu đồng, 99% đó là lừa đảo.</li>\n                    <li><strong>Các đường link điều hướng bị lỗi:</strong> Khi bạn click vào các mục như "Giới thiệu", "Liên hệ" trên trang giả mạo, thường sẽ không dẫn đi đâu hoặc quay lại trang chủ.</li>\n                </ol>\n                <p>Hãy luôn luôn cẩn trọng trước khi nhập bất kỳ thông tin quan trọng nào lên mạng. Kiểm tra thật kỹ thanh địa chỉ web là thói mãnh mẽ giúp bạn bảo vệ tài sản của mình.</p>', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1000&q=80', 0, 5176, 'security, website, phishing, tips', 1, '2026-02-26 02:48:39', '2026-03-17 19:57:58'),
	(28, 'Hướng dẫn bảo vệ tài khoản ngân hàng trong mùa cao điểm', 'huong-dan-bao-ve-tai-khoan-ngan-hang-trong-mua-cao-diem-lADmO', 'Các vụ mất tiền trong tài khoản ngân hàng liên tục diễn ra do người dân bị lừa cài ứng dụng chứa mã độc. Xem ngay hướng dẫn bảo mật từ chuyên gia.', '<h3>Bảo vệ "ví tiền" online của bạn trước các loại mã độc</h3>\n                <p>Hiện nay, thay vì lừa lấy OTP, tội phạm mạng đã chuyển sang hình thức tinh vi hơn: lừa người dân cài đặt các ứng dụng giả mạo ứng dụng Chính phủ, Thuế, Bảo hiểm xã hội để chiếm quyền điều khiển điện thoại.</p>\n                <p>Khi đã cài đặt, ứng dụng này sẽ bí mật đọc tin nhắn OTP, theo dõi các thao tác cá nhân và tự động thực hiện lệnh chuyển tiền mà người dùng không hề hay biết.</p>\n                <h4>Quy tắc vàng để an toàn</h4>\n                <ul>\n                    <li><strong>Chỉ cài đặt ứng dụng từ cửa hàng chính thống:</strong> Apple App Store và Google Play Store. Tuyệt đối không cài các file .apk từ link lạ.</li>\n                    <li><strong>Không bao giờ chia sẻ OTP:</strong> Dù người gọi có tự xưng là công an, nhân viên ngân hàng hay cán bộ thuế.</li>\n                    <li><strong>Kích hoạt sinh trắc học:</strong> Hãy sử dụng FaceID hoặc vân tay để xác thực giao dịch thay vì chỉ dùng mã PIN.</li>\n                    <li><strong>Hạn chế hạn mức chuyển tiền:</strong> Chỉ để hạn mức đủ dùng trong ngày trên ứng dụng ngân hàng để giảm thiểu rủi ro nếu chẳng may bị hack.</li>\n                </ul>\n                <p>Nếu nghi ngờ điện thoại bị nhiễm mã độc, hãy thực hiện khôi phục cài đặt gốc ngay lập tức để xóa sạch các phần mềm gián điệp và liên hệ ngân hàng để khóa tài khoản tạm thời.</p>', 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=1000&q=80', 0, 2062, 'ngan-hang, bao-mat, app-gia-mao, otp', 1, '2026-03-14 02:48:59', '2026-03-17 19:57:58'),
	(29, 'Lừa đảo mạo danh admin CheckScam để chiếm đoạt tài sản', 'lua-dao-mao-danh-admin-checkscam-de-chiem-doat-tai-san-PAcQf', 'Nhiều kẻ xấu đã lập các tài khoản Facebook giả mạo admin của hệ thống CheckScam để lừa phí "kiểm tra thông tin" của người dùng.', '<h3>Cảnh báo mạo danh đội ngũ quản trị CheckScam</h3>\n                <p>Hệ thống CheckScam xin gửi thông báo quan trọng đến toàn thể người dùng về tình trạng mạo danh cán bộ, quản trị viên của chúng tôi để trục lợi cá nhân.</p>\n                <p><strong>Thủ đoạn của chúng:</strong> Các đối tượng sẽ sử dụng tên, hình ảnh và logo của CheckScam để tạo các trang fanpage hoặc tài khoản cá nhân. Khi người dùng nhắn tin nhờ kiểm tra thông tin một tài khoản lừa đảo khác, chúng sẽ yêu cầu đóng phí "tra cứu chuyên sâu" hoặc phí "mở hồ sơ den" với giá từ vài trăm nghìn đến hàng triệu đồng.</p>\n                <p>Chúng tôi xin khẳng định <strong>CheckScam là hệ thống tra cứu MIỄN PHÍ</strong> dành cho cộng đồng. Chúng tôi không bao giờ chủ động nhắn tin yêu cầu người dùng chuyển tiền để kiểm tra thông tin hay giải quyết khiếu nại.</p>\n                <h4>Cách xử lý khi gặp đối tượng mạo danh</h4>\n                <p>Người dân nên thực hiện các bước sau:</p>\n                <ol>\n                    <li>Chụp ảnh màn hình cuộc hội thoại và trang cá nhân của đối tượng.</li>\n                    <li>Gửi phản ánh ngay cho chúng tôi qua kênh liên hệ chính thức trên website.</li>\n                    <li>Báo cáo (Report) tài khoản giả mạo đó cho Facebook/Telegram.</li>\n                </ol>\n                <p>Hãy là người dùng thông thái. Hãy cùng nhau xây dựng một cộng đồng CheckScam minh bạch và an toàn.</p>', 'https://images.unsplash.com/photo-1593113598332-cd288d649433?w=1000&q=80', 1, 1965, 'checkscam, canh-bao, mạo-danh, bao-ve-nguoi-dung', 1, '2026-02-23 21:44:45', '2026-03-17 19:57:58'),
	(30, 'Deepfake - Công nghệ lừa đảo cuộc gọi video tinh vi năm 2024', 'deepfake-cong-nghe-lua-dao-cuoc-goi-video-tinh-vi-nam-2024-1tRlP', 'Tội phạm mạng đang sử dụng AI để giả mạo hình ảnh và giọng nói của người thân để vay tiền. Cách nhận diện và phòng tránh hiệu quả.', '<h3>Khi mắt thấy, tai nghe chưa chắc đã là thật</h3>\n                <p>Deepfake là một công nghệ sử dụng trí tuệ nhân tạo để tạo ra các video giả mạo trông như thật. Gần đây, nhiều người dân đã bị lừa hàng trăm triệu đồng khi nhận được cuộc gọi video từ "con cái" hoặc "người thân" đang ở nước ngoài nhờ chuyển tiền gấp.</p>\n                <p>Các video này thường có hình ảnh mờ ảo, giọng nói hơi đứt quãng và thời gian gọi rất ngắn để nạn nhân không kịp nhận ra sự bất thường.</p>\n                <h4>Dấu hiệu nhận biết cuộc gọi Deepfake</h4>\n                <ul>\n                    <li>Góc nhìn nghiêng của khuôn mặt thường bị biến dạng hoặc mờ đi.</li>\n                    <li>Màu da không đồng nhất giữa khuôn mặt và cổ.</li>\n                    <li>Chuyển động môi không khớp hoàn toàn với lời nói.</li>\n                    <li>Mạch văn và cách dùng từ có vẻ lạ so với thói quen của người thân.</li>\n                </ul>\n                <p><strong>Lời khuyên:</strong> Khi nhận được yêu cầu chuyển tiền qua video call, hãy ngắt máy và gọi lại bằng số điện thoại di động thông thường. Hoặc hãy hỏi một câu hỏi mà chỉ hai người mới biết để kiểm tra danh tính.</p>', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1000&q=80', 0, 9079, 'deepfake, ai, lua-dao, cong-nghe', 1, '2026-03-01 14:47:32', '2026-03-17 19:57:58');
